public class Sach{private int id,namXuatBan;private String maSach,tenSach,tacGia,nhaXuatBan;public Sach(){}public Sach(int i,String m,String t,String a,String n,int y){id=i;maSach=m;tenSach=t;tacGia=a;nhaXuatBan=n;namXuatBan=y;}public int getId(){return id;}public void setId(int v){id=v;}public String getMaSach(){return maSach;}public void setMaSach(String v){maSach=v;}public String getTenSach(){return tenSach;}public void setTenSach(String v){tenSach=v;}public String getTacGia(){return tacGia;}public void setTacGia(String v){tacGia=v;}public String getNhaXuatBan(){return nhaXuatBan;}public void setNhaXuatBan(String v){nhaXuatBan=v;}public int getNamXuatBan(){return namXuatBan;}public void setNamXuatBan(int v){namXuatBan=v;}}
